package com.oms.order.service;

import com.fasterxml.jackson.databind.node.ObjectNode;
import org.junit.jupiter.api.Test;
import java.util.*;
import static com.oms.order.service.OrderValues.*;
import static org.junit.jupiter.api.Assertions.*;

class OrderDocumentInfoTest {
    static ObjectNode trade(){try{
        ObjectNode t=(ObjectNode)JSON.readTree(TmallOrderParserTest.payload("270.00")).path("trade_fullinfo_get_response").path("trade");
        t.put("post_fee","10.00").put("discount_fee","20.00").put("adjust_fee","0.00").put("total_fee","270.00").put("pay_time","2026-10-21 13:00:00").put("buyer_message","请分开包装").put("seller_memo","核对规格");
        ObjectNode a=(ObjectNode)t.path("orders").path("order").get(0);a.put("num",1).put("price","100.00").put("discount_fee","10.00").put("part_mjz_discount","5.00").put("adjust_fee","0.00").put("payment","90.00").put("divide_order_fee","85.00");
        ObjectNode b=a.deepCopy();b.put("oid","987654321012345680").put("outer_sku_id","B").put("price","200.00").put("part_mjz_discount","15.00").put("payment","190.00").put("divide_order_fee","175.00");((com.fasterxml.jackson.databind.node.ArrayNode)t.path("orders").path("order")).add(b);return t;
    }catch(Exception e){throw new RuntimeException(e);}}
    static String payload(ObjectNode trade){return encode(Collections.singletonMap("trade_fullinfo_get_response",Collections.singletonMap("trade",trade)));}
    @SuppressWarnings("unchecked") static List<Map<String,Object>> lines(Map<String,Object> doc){return (List<Map<String,Object>>)doc.get("lines");}
    @Test void ownDiscountAndOrderShareAreNotCountedTwice(){Map<String,Object> d=OrderDocumentInfo.parse(trade());assertEquals("300.00",d.get("sales_amount"));assertEquals("40.00",d.get("discount_total"));assertEquals("260.00",d.get("goods_payment"));assertEquals("270.00",d.get("payment"));assertEquals("10.00",d.get("buyer_freight"));assertEquals("MATCHED",d.get("check_state"));assertEquals("15.00",lines(d).get(0).get("discount_total"));assertEquals("25.00",lines(d).get(1).get("discount_total"));assertEquals("987654321012345679",lines(d).get(0).get("platform_oid"));}
    @Test void singleChildPaymentIncludingFreightIsNormalizedForGiftThreshold(){ObjectNode t=trade();((com.fasterxml.jackson.databind.node.ArrayNode)t.path("orders").path("order")).remove(1);t.put("payment","95.00").put("discount_fee","5.00");((ObjectNode)t.path("orders").path("order").get(0)).put("payment","95.00").put("divide_order_fee","95.00");TmallOrderParser.Trade parsed=new TmallOrderParser().parse(payload(t));assertEquals("85.00",parsed.lines.get(0).payment.toPlainString());assertEquals("85.00",lines(parsed.document).get(0).get("goods_payment"));assertEquals("MATCHED",parsed.document.get("check_state"));}
    @Test void unknownIsNotZeroAndMalformedMoneyIsReported(){ObjectNode t=trade();t.remove("post_fee");((ObjectNode)t.path("orders").path("order").get(0)).remove("price");Map<String,Object> d=OrderDocumentInfo.parse(t);assertNull(d.get("buyer_freight"));assertNull(d.get("sales_amount"));assertEquals("INCOMPLETE",d.get("check_state"));t.put("post_fee","n/a");d=OrderDocumentInfo.parse(t);assertEquals("INVALID",d.get("check_state"));assertFalse(((List<?>)d.get("issues")).isEmpty());}
    @Test void zeroFreightAndNegativePriceAdjustmentAreValid(){ObjectNode t=trade();t.put("post_fee","0.00").put("payment","257.00").put("adjust_fee","-3.00");((ObjectNode)t.path("orders").path("order").get(0)).put("adjust_fee","-3.00").put("divide_order_fee","82.00");Map<String,Object> d=OrderDocumentInfo.parse(t);assertEquals("MATCHED",d.get("check_state"));assertEquals("-3.00",d.get("adjustment"));assertEquals("0.00",d.get("buyer_freight"));}
    @Test void differenceIsExactAndPromotionDetailsAreExplanatory(){ObjectNode t=trade();t.put("payment","270.01");t.putObject("promotion_details").putArray("promotion_detail").addObject().put("id","987654321012345678").put("promotion_name","订单券").put("discount_fee","20.00");Map<String,Object> d=OrderDocumentInfo.parse(t);assertEquals("0.01",d.get("payment_difference"));assertEquals("DIFFERENCE",d.get("check_state"));assertEquals("40.00",d.get("discount_total"));assertEquals(1,((List<?>)d.get("promotions")).size());}
    @Test void salesAmountsKeepPrecisionAndMissingSharesAreNotInvented(){ObjectNode t=trade();ObjectNode a=(ObjectNode)t.path("orders").path("order").get(0);a.put("price","90071992547409.91").put("num",2);a.remove("part_mjz_discount");Map<String,Object> d=OrderDocumentInfo.parse(t);assertEquals("180143985094819.82",lines(d).get(0).get("sales_amount"));assertNull(lines(d).get(0).get("discount_total"));assertNull(d.get("discount_share_difference"));}
    @Test void commercialChangesAffectFingerprintButRemarksDoNot(){ObjectNode t=trade();TmallOrderParser parser=new TmallOrderParser();String original=parser.parse(payload(t)).fingerprint;t.put("buyer_message","新留言");assertEquals(original,parser.parse(payload(t)).fingerprint);t.put("post_fee","11.00");assertNotEquals(original,parser.parse(payload(t)).fingerprint);}
    @Test void offsettingChildErrorsCannotPassAnOrderTotalCheck(){ObjectNode t=trade();((ObjectNode)t.path("orders").path("order").get(0)).put("divide_order_fee","80.00");((ObjectNode)t.path("orders").path("order").get(1)).put("divide_order_fee","180.00");Map<String,Object> d=OrderDocumentInfo.parse(t);assertEquals("0.00",d.get("payment_difference"));assertEquals("0.00",d.get("line_difference"));assertEquals("DIFFERENCE",d.get("check_state"));assertEquals("5.00",lines(d).get(0).get("payment_difference"));assertEquals("-5.00",lines(d).get(1).get("payment_difference"));assertEquals(2,((List<?>)d.get("differences")).size());}
    @Test void unconfirmedCalculatedAmountDoesNotOverwritePlatformTransactionAmount(){ObjectNode t=trade();((ObjectNode)t.path("orders").path("order").get(0)).put("price","90071992547409.91").put("divide_order_fee","90.00");TmallOrderParser.Trade parsed=new TmallOrderParser().parse(payload(t));assertEquals("90.00",parsed.lines.get(0).payment.toPlainString());assertEquals("DIFFERENCE",parsed.document.get("check_state"));}
}
